insert into passages (id, text, difficulty_level, b, active) values
('06fc751c-b87c-4259-9adf-47b73c902e23', 'Bioluminescence, the ability of living organisms to produce and emit light, occurs in a surprisingly wide range of species, from deep-sea fish and jellyfish to fireflies and certain fungi. This light is produced through a chemical reaction involving a light-emitting molecule called luciferin and an enzyme called luciferase. Different species use bioluminescence for different purposes. Some deep-sea creatures use it to lure prey closer, while others flash light patterns to communicate with potential mates or to startle predators long enough to escape. Fireflies are perhaps the most familiar example, using rhythmic flashes to attract partners during summer evenings. Scientists have also found practical applications for bioluminescent proteins in medical research, using them as markers to track cellular processes and monitor the effectiveness of new drugs. As researchers continue to study the chemistry behind bioluminescence, they hope to develop new tools for both biological research and, potentially, more energy-efficient lighting technology inspired by nature''s own glow.', 3, 0.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('6e551387-e897-46fe-a488-91bfe9b6eeae', 'sentence_completion', 'The company''s new advertising campaign ___ a significant increase in sales.', NULL, '[{"id": "a", "text": "produced"}, {"id": "d", "text": "forgot"}, {"id": "b", "text": "prevented"}, {"id": "c", "text": "ignored"}]'::jsonb, 0, '{"strategy": "new advertising campaign = קמפיין פרסום חדש. מה עושה קמפיין מוצלח למכירות?", "correct_reason": "produced = הפיק/יצר. קמפיין מוצלח מייצר עלייה במכירות.", "options_analysis": ["נכון! produced = יצר — קמפיין מוצלח יוצר עלייה במכירות", "forgot = שכח — לא רלוונטי", "prevented = מנע — הפוך מהצלחת קמפיין", "ignored = התעלם מ- — לא רלוונטי לתוצאה"]}', 1.51, 0.0, 0.25, 3, 'ai', NULL, true),
('2b0c310b-9036-46f2-902d-b929b391f327', 'sentence_completion', 'The scientist''s discovery ___ the way researchers understand the disease.', NULL, '[{"id": "b", "text": "confused"}, {"id": "d", "text": "transformed"}, {"id": "a", "text": "hid"}, {"id": "c", "text": "ignored"}]'::jsonb, 1, '{"strategy": "discovery...understand the disease = תגלית...הבנת המחלה. מה עושה תגלית משמעותית להבנה?", "correct_reason": "transformed = שינתה מהותית. תגלית חשובה משנה הבנה.", "options_analysis": ["confused = בלבלה — הפוך מתרומה מדעית", "נכון! transformed = שינתה מהותית — מתאים לתגלית פורצת דרך", "hid = הסתירה — הפוך ממטרת מחקר", "ignored = התעלמה מ- — לא רלוונטי לתגלית"]}', 1.56, 0.0, 0.25, 3, 'ai', NULL, true),
('645f5f0b-1cf3-417f-8858-ea17aceba6cd', 'sentence_completion', 'The company had to ___ several employees due to falling profits.', NULL, '[{"id": "d", "text": "reward"}, {"id": "b", "text": "hire"}, {"id": "c", "text": "lay off"}, {"id": "a", "text": "promote"}]'::jsonb, 2, '{"strategy": "due to falling profits = בגלל ירידה ברווחים. מה עושה חברה בקשיים כלכליים?", "correct_reason": "lay off = לפטר. ירידה ברווחים מובילה לפיטורים.", "options_analysis": ["reward = לתגמל — לא סביר במצב כלכלי קשה", "hire = לגייס — הפוך ממצב כלכלי קשה", "נכון! lay off = לפטר — תגובה נפוצה לירידה ברווחים", "promote = לקדם — לא סביר במצב כלכלי קשה"]}', 1.56, 0.0, 0.25, 3, 'ai', NULL, true),
('2d95cbaf-9173-4557-aa03-e67a9d5f0e9c', 'sentence_completion', 'The new highway will ___ traffic congestion in the city center.', NULL, '[{"id": "c", "text": "increase"}, {"id": "a", "text": "celebrate"}, {"id": "b", "text": "ignore"}, {"id": "d", "text": "ease"}]'::jsonb, 3, '{"strategy": "new highway = כביש מהיר חדש. מה עושה כביש חדש לפקקים?", "correct_reason": "ease = להקל. כביש חדש בד''כ מקל על פקקים.", "options_analysis": ["increase = להגביר — הפוך ממטרת כביש חדש", "celebrate = לחגוג — לא רלוונטי", "ignore = להתעלם מ- — לא רלוונטי", "נכון! ease = להקל — מטרה טבעית של כביש חדש"]}', 1.08, 0.0, 0.25, 3, 'ai', NULL, true),
('eb625bc4-03fe-438a-833b-10664a5cf31e', 'sentence_completion', 'The manager''s calm response helped to ___ the tense situation.', NULL, '[{"id": "c", "text": "defuse"}, {"id": "b", "text": "ignore"}, {"id": "d", "text": "worsen"}, {"id": "a", "text": "create"}]'::jsonb, 0, '{"strategy": "calm response...tense situation = תגובה רגועה...מצב מתוח. מה עושה תגובה רגועה למתח?", "correct_reason": "defuse = להרגיע/לפרק. תגובה רגועה מפרקת מתח.", "options_analysis": ["נכון! defuse = להרגיע — מתאים לתגובה רגועה במצב מתוח", "ignore = להתעלם מ- — לא פתרון פעיל", "worsen = להחמיר — הפוך מתגובה רגועה", "create = ליצור — הפוך, המתח כבר קיים"]}', 1.44, 0.0, 0.25, 3, 'ai', NULL, true),
('64339eba-b72b-41ae-8d59-3c35f8f2449a', 'sentence_completion', 'The committee will ___ the final decision after reviewing all the evidence.', NULL, '[{"id": "b", "text": "avoid"}, {"id": "d", "text": "make"}, {"id": "c", "text": "forget"}, {"id": "a", "text": "hide"}]'::jsonb, 1, '{"strategy": "after reviewing all the evidence = אחרי בדיקת כל הראיות. מה עושה ועדה אחרי בדיקה?", "correct_reason": "make = לקבל/לגבש החלטה. ועדה מקבלת החלטה אחרי בדיקה.", "options_analysis": ["avoid = להימנע מ- — סותר את קבלת ההחלטה", "נכון! make = לקבל החלטה — פעולה טבעית אחרי בדיקה", "forget = לשכוח — לא רלוונטי לקבלת החלטה", "hide = להסתיר — לא רלוונטי"]}', 1.11, 0.0, 0.25, 3, 'ai', NULL, true),
('688d47e4-2840-4504-a642-1cbe6b79e594', 'sentence_completion', 'The new law aims to ___ small businesses from unfair competition.', NULL, '[{"id": "b", "text": "harm"}, {"id": "c", "text": "confuse"}, {"id": "a", "text": "protect"}, {"id": "d", "text": "ignore"}]'::jsonb, 2, '{"strategy": "aims to = מטרתה. מה חוק חדש עושה לעסקים קטנים מול תחרות לא הוגנת?", "correct_reason": "protect = להגן. חוקים נועדים להגן על עסקים קטנים.", "options_analysis": ["harm = לפגוע — הפוך ממטרת החוק", "confuse = לבלבל — לא רלוונטי לחוק", "נכון! protect = להגן — מטרה טבעית של חוק כזה", "ignore = להתעלם מ- — סותר ''aims to''"]}', 1.14, 0.0, 0.25, 3, 'ai', NULL, true),
('53097438-9aca-4956-b4cf-d8f6bb755733', 'sentence_completion', 'The athlete''s dedication and hard work eventually ___ in an Olympic medal.', NULL, '[{"id": "a", "text": "disappeared"}, {"id": "c", "text": "failed"}, {"id": "b", "text": "hesitated"}, {"id": "d", "text": "resulted"}]'::jsonb, 3, '{"strategy": "dedication and hard work eventually = מסירות ועבודה קשה בסופו של דבר. מה קורה כתוצאה ממסירות?", "correct_reason": "resulted = הסתכם ב-. מסירות ועבודה קשה מסתכמות בהצלחה.", "options_analysis": ["disappeared = נעלם — לא הגיוני", "failed = נכשל — סותר את ההיגיון של מסירות מובילה להצלחה", "hesitated = היסס — לא מתאר תוצאה", "נכון! resulted = הסתכם — מתאים לתוצאה חיובית של מאמץ"]}', 1.46, 0.0, 0.25, 3, 'ai', NULL, true),
('c87686b4-7945-449a-bef0-d089d144fb81', 'sentence_completion', 'The government introduced new measures to ___ pollution in major cities.', NULL, '[{"id": "c", "text": "curb"}, {"id": "a", "text": "increase"}, {"id": "b", "text": "celebrate"}, {"id": "d", "text": "ignore"}]'::jsonb, 0, '{"strategy": "new measures = אמצעים חדשים. מה עושים אמצעים חדשים לזיהום?", "correct_reason": "curb = לרסן/לבלום. אמצעים ממשלתיים נועדו לרסן זיהום.", "options_analysis": ["נכון! curb = לרסן — מטרה טבעית של אמצעים לזיהום", "increase = להגביר — הפוך ממטרת אמצעים סביבתיים", "celebrate = לחגוג — לא רלוונטי", "ignore = להתעלם מ- — סותר ''measures''"]}', 0.95, 0.0, 0.25, 3, 'ai', NULL, true),
('2b3cdca7-b44c-45f6-a7f6-6fd2925480c7', 'sentence_completion', 'The witness''s account ___ significantly from what the police had initially believed.', NULL, '[{"id": "d", "text": "matched"}, {"id": "c", "text": "differed"}, {"id": "b", "text": "confirmed"}, {"id": "a", "text": "supported"}]'::jsonb, 1, '{"strategy": "differed from what police believed = שונה ממה שהמשטרה האמינה. מה קרה בין העדות לאמונה המקורית?", "correct_reason": "differed = היה שונה. עדות שסותרת אמונה קודמת היא שונה ממנה.", "options_analysis": ["matched = התאים — הפוך מ''differed''", "נכון! differed = היה שונה — מתאים לניגוד בין עדות לציפייה", "confirmed = אישרר — הפוך מסתירה", "supported = תמך ב- — הפוך מסתירה"]}', 1.33, 0.0, 0.25, 3, 'ai', NULL, true),
('5b8364be-5f8f-43d2-bce8-cb991a548d0c', 'sentence_completion', 'The new software update ___ several bugs that had frustrated users.', NULL, '[{"id": "b", "text": "created"}, {"id": "c", "text": "caused"}, {"id": "d", "text": "fixed"}, {"id": "a", "text": "hid"}]'::jsonb, 2, '{"strategy": "that had frustrated users = שתסכלו משתמשים. מה עושה עדכון תוכנה לבאגים מתסכלים?", "correct_reason": "fixed = תיקן. עדכון תוכנה מתוקן מטפל בבאגים.", "options_analysis": ["created = יצר — הפוך ממטרת עדכון", "caused = גרם ל- — הפוך, העדכון נועד לתקן לא לגרום", "נכון! fixed = תיקן — מטרה טבעית של עדכון תוכנה", "hid = הסתיר — לא פותר את הבעיה"]}', 1.35, 0.0, 0.25, 3, 'ai', NULL, true),
('72bc8c29-53b3-4e27-84f2-8c2e03afb9c3', 'sentence_completion', 'The teacher''s patience ___ even the most difficult students to succeed.', NULL, '[{"id": "a", "text": "prevented"}, {"id": "c", "text": "stopped"}, {"id": "b", "text": "refused"}, {"id": "d", "text": "helped"}]'::jsonb, 3, '{"strategy": "even the most difficult students to succeed = אפילו התלמידים הקשים ביותר להצליח. מה עושה סבלנות לתלמידים?", "correct_reason": "helped = עזרה. סבלנות עוזרת גם לתלמידים קשים להצליח.", "options_analysis": ["prevented = מנעה — הפוך מסייעת להצלחה", "stopped = עצרה — הפוך מסיוע", "refused = סירבה — לא רלוונטי לתכונת סבלנות", "נכון! helped = עזרה — מתאים לתפקיד הסבלנות בהצלחה"]}', 1.57, 0.0, 0.25, 3, 'ai', NULL, true),
('3a737640-5a91-4a37-b1b3-f38691cc76df', 'restatement', 'The company expanded into international markets to increase its revenue.', NULL, '[{"id": "c", "text": "To increase its revenue, the company expanded into international markets."}, {"id": "b", "text": "The company avoided international markets entirely."}, {"id": "a", "text": "The company''s revenue decreased after international expansion."}, {"id": "d", "text": "International markets had no effect on the company''s revenue."}]'::jsonb, 0, '{"strategy": "expanded to increase = הרחיבה כדי להגדיל. מטרה.", "correct_reason": "אותה מטרה בדיוק.", "options_analysis": ["נכון! אותה מטרה בדיוק", "סותר לגמרי — החברה כן הרחיבה לשווקים בינלאומיים", "סותר את המטרה — הפסקה לא מדברת על ירידה", "סותר את הקשר הסיבתי המפורש במקור"]}', 1.33, 0.0, 0.25, 3, 'ai', NULL, true),
('2facd17e-ce7f-4f7d-80a6-ccd4258fd416', 'restatement', 'The film received mixed reviews, with some critics praising it and others condemning it.', NULL, '[{"id": "a", "text": "Every critic condemned the film without exception."}, {"id": "d", "text": "Critics were divided, some praising the film and others criticizing it."}, {"id": "b", "text": "All critics agreed that the film was excellent."}, {"id": "c", "text": "No critics reviewed the film at all."}]'::jsonb, 1, '{"strategy": "mixed reviews...some...others = ביקורות מעורבות...חלק...אחרים. חלוקת דעות.", "correct_reason": "אותה חלוקת דעות בדיוק.", "options_analysis": ["סותר ''praising it'' — לא כולם גינו", "נכון! אותה חלוקת דעות בדיוק", "סותר ''mixed reviews'' — לא היה קונצנזוס", "סותר לגמרי — היו ביקורות"]}', 1.5, 0.0, 0.25, 3, 'ai', NULL, true),
('f774c7fa-616f-40ed-a802-9f9877eb96f0', 'restatement', 'The negotiations dragged on for months without reaching any agreement.', NULL, '[{"id": "c", "text": "The negotiations ended after just one day."}, {"id": "a", "text": "An agreement was reached quickly."}, {"id": "d", "text": "The negotiations continued for months but produced no agreement."}, {"id": "b", "text": "There were no negotiations at all."}]'::jsonb, 2, '{"strategy": "dragged on...without agreement = נמשך...בלי הסכם. משך זמן וחוסר תוצאה.", "correct_reason": "אותה משמעות בדיוק: המשיך זמן רב בלי הסכם.", "options_analysis": ["סותר ''dragged on for months''", "סותר ''dragged on for months''", "נכון! אותה משמעות בדיוק: נמשך חודשים בלי הסכם", "סותר לגמרי — היה מו''מ"]}', 0.94, 0.0, 0.25, 3, 'ai', NULL, true),
('13260f4e-3409-42a9-b6e7-187315467065', 'restatement', 'The city invested heavily in renewable energy to reduce its carbon footprint.', NULL, '[{"id": "d", "text": "The city avoided investing in renewable energy."}, {"id": "c", "text": "The city''s carbon footprint increased due to renewable energy."}, {"id": "b", "text": "Renewable energy had no connection to the city''s plans."}, {"id": "a", "text": "To reduce its carbon footprint, the city invested heavily in renewable energy."}]'::jsonb, 3, '{"strategy": "invested to reduce = השקיעה כדי להפחית. מטרה.", "correct_reason": "אותה מטרה בדיוק.", "options_analysis": ["סותר ''invested heavily''", "הפוך — אנרגיה מתחדשת אמורה להפחית, לא להגדיל", "סותר את הקשר המפורש במקור", "נכון! אותה מטרה בדיוק"]}', 1.52, 0.0, 0.25, 3, 'ai', NULL, true),
('8bb4c295-d8d4-4681-ae65-aa1f61772f08', 'restatement', 'The new policy was implemented gradually to avoid disrupting daily operations.', NULL, '[{"id": "d", "text": "To avoid disrupting daily operations, the policy was implemented gradually."}, {"id": "c", "text": "Daily operations were disrupted despite the gradual implementation."}, {"id": "a", "text": "The policy was implemented all at once, causing major disruption."}, {"id": "b", "text": "The policy was never implemented."}]'::jsonb, 0, '{"strategy": "implemented gradually to avoid = יושמה בהדרגה כדי להימנע. מטרה.", "correct_reason": "אותה מטרה בדיוק.", "options_analysis": ["נכון! אותה מטרה בדיוק", "לא נאמר במקור שהייתה הפרעה בפועל", "הפוך — ''all at once'' סותר ''gradually''", "סותר ''was implemented''"]}', 0.93, 0.0, 0.25, 3, 'ai', NULL, true),
('5c710d12-b486-42e4-b4ea-9de7a38026b4', 'restatement', 'The study''s findings contradicted much of the previous research on the topic.', NULL, '[{"id": "a", "text": "No previous research existed on this topic."}, {"id": "d", "text": "The study''s findings went against much of the earlier research."}, {"id": "b", "text": "The study''s findings were consistent with earlier studies."}, {"id": "c", "text": "The study''s findings matched all previous research exactly."}]'::jsonb, 1, '{"strategy": "contradicted previous research = סתרה מחקר קודם. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר ''previous research'' — הוא כן היה קיים", "נכון! אותה משמעות בדיוק: התנגד למחקר מוקדם", "הפוך — ''consistent'' סותר ''contradicted''", "הפוך — ''matched exactly'' סותר ''contradicted''"]}', 0.95, 0.0, 0.25, 3, 'ai', NULL, true),
('a590ba70-39aa-4f21-8d66-6c86284c8cd4', 'restatement', 'The organization relies on volunteers to carry out most of its work.', NULL, '[{"id": "b", "text": "The organization has no volunteers at all."}, {"id": "d", "text": "Paid staff carry out all of the organization''s work."}, {"id": "c", "text": "Most of the organization''s work is carried out by volunteers."}, {"id": "a", "text": "The organization refuses to use volunteers."}]'::jsonb, 2, '{"strategy": "relies on volunteers = תלויה במתנדבים. פרט תפעולי.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר לגמרי — יש מתנדבים", "סותר ''relies on volunteers'' לחלוטין", "נכון! אותה משמעות בדיוק", "סותר ''relies on volunteers''"]}', 1.59, 0.0, 0.25, 3, 'ai', NULL, true),
('ebf82601-498d-4802-960e-290ed31de9f2', 'restatement', 'The company''s reputation suffered greatly after the product recall.', NULL, '[{"id": "c", "text": "The product recall happened after the company''s reputation suffered."}, {"id": "a", "text": "The product recall had no impact on the company''s reputation."}, {"id": "d", "text": "The company''s reputation improved after the product recall."}, {"id": "b", "text": "After the product recall, the company''s reputation suffered greatly."}]'::jsonb, 3, '{"strategy": "reputation suffered after = מוניטין נפגע אחרי. פרט זמן וסיבה.", "correct_reason": "אותה עובדה וסדר בדיוק.", "options_analysis": ["הופך את סדר האירועים", "סותר את ההשפעה שצוינה במפורש", "הפוך — ''improved'' סותר ''suffered''", "נכון! אותה עובדה וסדר בדיוק"]}', 1.5, 0.0, 0.25, 3, 'ai', NULL, true),
('10b3cfb1-d12e-4d11-ab8d-8dc416d29355', 'restatement', 'The town council approved the budget after extensive debate.', NULL, '[{"id": "d", "text": "After extensive debate, the town council approved the budget."}, {"id": "c", "text": "There was no debate about the budget at all."}, {"id": "a", "text": "The town council rejected the budget without any debate."}, {"id": "b", "text": "The budget was approved before any discussion took place."}]'::jsonb, 0, '{"strategy": "approved after debate = אושר אחרי דיון. פרט זמן.", "correct_reason": "אותה עובדה בדיוק, סדר מילים הפוך.", "options_analysis": ["נכון! אותה עובדה בדיוק", "סותר ''extensive debate''", "הפוך — ''rejected'' סותר ''approved''", "הופך את סדר האירועים"]}', 1.35, 0.0, 0.25, 3, 'ai', NULL, true),
('52b44263-e977-4cbb-88de-a25ef910f5ee', 'restatement', 'The airline''s new policy allows passengers to change flights without extra fees.', NULL, '[{"id": "d", "text": "The airline charges extra fees for every flight change."}, {"id": "a", "text": "Passengers can change flights without extra fees under the airline''s new policy."}, {"id": "c", "text": "The new policy forbids passengers from changing flights."}, {"id": "b", "text": "The airline removed its flight-change option entirely."}]'::jsonb, 1, '{"strategy": "allows...without extra fees = מאפשרת...ללא עלות נוספת. פרט מדיניות.", "correct_reason": "אותה עובדה בדיוק.", "options_analysis": ["הפוך — ''charges extra fees'' סותר ''without extra fees''", "נכון! אותה עובדה בדיוק", "הפוך — ''forbids'' סותר ''allows''", "סותר לגמרי — האפשרות עדיין קיימת"]}', 1.25, 0.0, 0.25, 3, 'ai', NULL, true),
('b83c8853-6b68-4c5a-82b7-36df712d85bd', 'restatement', 'The researchers were surprised by how quickly the disease spread among the population.', NULL, '[{"id": "c", "text": "The researchers expected the disease to spread quickly."}, {"id": "a", "text": "The researchers had no interest in how the disease spread."}, {"id": "b", "text": "The disease spread much more slowly than the researchers expected."}, {"id": "d", "text": "The disease did not spread at all."}]'::jsonb, 2, '{"strategy": "surprised by how quickly = הופתעו מהמהירות. משתמע: לא ציפו למהירות כזו.", "correct_reason": "אותה משמעות בדיוק: מהירות ההתפשטות הייתה מעבר לציפיות (איטית יותר מהצפוי היה מפתיע פחות).", "options_analysis": ["סותר ''surprised'' — לא ציפו למהירות", "סותר את עצם קיום המחקר על המחלה", "נכון! אם הופתעו מהמהירות, המשמעות היא שציפו למשהו איטי יותר", "סותר לגמרי — המחלה כן התפשטה"]}', 0.97, 0.0, 0.25, 3, 'ai', NULL, true),
('81b5eea2-644a-4112-9150-3cfcb2b2e187', 'reading_comprehension', 'What is the passage mainly about?', '06fc751c-b87c-4259-9adf-47b73c902e23', '[{"id": "d", "text": "Why deep-sea fish are dangerous"}, {"id": "a", "text": "How fireflies mate during the summer"}, {"id": "c", "text": "The chemistry of luciferin only"}, {"id": "b", "text": "Bioluminescence, its purposes in nature, and its scientific applications"}]'::jsonb, 3, '{"strategy": "שאלת רעיון מרכזי — הפסקה סוקרת את תופעת הביולומינסנציה, שימושיה בטבע ויישומיה המדעיים.", "correct_reason": "כל הפסקה עוסקת בתופעה, בשימושיה השונים בטבע ובשימושים מדעיים שלה.", "options_analysis": ["לא מוזכר בפסקה כלל", "פרט אחד מיני רבים, לא הנושא הכולל", "פרט טכני שמוזכר, לא הנושא הכולל", "נכון! התופעה, שימושיה בטבע ויישומיה המדעיים = הנושא הכולל"]}', 1.3, 0.0, 0.25, 3, 'ai', NULL, true),
('4d82eaca-2ecd-4359-9a83-85eca52940cd', 'reading_comprehension', 'According to the passage, what two components create bioluminescent light?', '06fc751c-b87c-4259-9adf-47b73c902e23', '[{"id": "a", "text": "A molecule called luciferin and an enzyme called luciferase"}, {"id": "d", "text": "Sunlight and chlorophyll"}, {"id": "c", "text": "Electricity and heat"}, {"id": "b", "text": "Water and oxygen"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את המרכיבים הכימיים בפסקה.", "correct_reason": "הפסקה אומרת: ''a light-emitting molecule called luciferin and an enzyme called luciferase''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.38, 0.0, 0.25, 3, 'ai', NULL, true),
('af70aed5-739c-4cd2-b92b-d63a00648c8a', 'reading_comprehension', 'Why do some deep-sea creatures use bioluminescence, according to the passage?', '06fc751c-b87c-4259-9adf-47b73c902e23', '[{"id": "d", "text": "To measure ocean depth"}, {"id": "a", "text": "To lure prey closer"}, {"id": "b", "text": "To purify water"}, {"id": "c", "text": "To generate heat"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את השימוש שמוזכר לגבי יצורי מעמקים.", "correct_reason": "הפסקה אומרת: ''Some deep-sea creatures use it to lure prey closer''.", "options_analysis": ["לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.05, 0.0, 0.25, 3, 'ai', NULL, true),
('c15baf3c-6cb7-4559-99a1-64e367462b7b', 'reading_comprehension', 'The word "startle" in the passage most closely means:', '06fc751c-b87c-4259-9adf-47b73c902e23', '[{"id": "d", "text": "to slowly attract"}, {"id": "c", "text": "to completely ignore"}, {"id": "a", "text": "to suddenly surprise or frighten"}, {"id": "b", "text": "to calmly inform"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''startle predators long enough to escape''.", "correct_reason": "startle = להפתיע/להבהיל בפתאומיות.", "options_analysis": ["הפוך — startle הוא פתאומי, לא איטי", "לא קשור למשמעות המילה", "נכון! startle = להפתיע/להבהיל בפתאומיות", "הפוך — startle הוא פתאומי, לא רגוע"]}', 1.13, 0.0, 0.25, 3, 'ai', NULL, true),
('0e46b4c7-0077-429f-9715-ca6b0cf23717', 'reading_comprehension', 'How do scientists use bioluminescent proteins in medical research, according to the passage?', '06fc751c-b87c-4259-9adf-47b73c902e23', '[{"id": "d", "text": "As a way to permanently cure diseases"}, {"id": "c", "text": "As a replacement for all medications"}, {"id": "b", "text": "As a substitute for surgical tools"}, {"id": "a", "text": "As markers to track cellular processes and monitor drug effectiveness"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את השימוש הרפואי שמוזכר בפסקה.", "correct_reason": "הפסקה אומרת: ''using them as markers to track cellular processes and monitor the effectiveness of new drugs''.", "options_analysis": ["לא נאמר בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה"]}', 1.02, 0.0, 0.25, 3, 'ai', NULL, true);